        const std::vector<std::byte> encoded(reinterpret_cast<const std::byte *>(kAvif),
                                             reinterpret_cast<const std::byte *>(kAvif) + sizeof(kAvif));
        auto decoded = Engine::Detail::decode_image_rgba8(encoded, std::filesystem::path{"test.avif"});
        assert(decoded.has_value());
